type LocaleContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: TranslationKey, params?: Record<string, string | number>) => string;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

function getInitialLocale(): Locale {
  try {
    const saved = window.localStorage.getItem(LOCALE_STORAGE_KEY);
    if (saved === 'en' || saved === 'ru') return saved;
    return 'en';
  } catch {
    return 'en';
  }
}

export function LocaleProvider({ children }: PropsWithChildren) {
  const [locale, setLocaleState] = useState<Locale>(getInitialLocale);
  const setLocale = (nextLocale: Locale) => {
    setLocaleState(nextLocale);
    try {
      window.localStorage.setItem(LOCALE_STORAGE_KEY, nextLocale);
    } catch {
      // Keep the locale for the current session if storage is unavailable.
    }
  };
  const value = useMemo(() => ({ locale, setLocale, t: (key: TranslationKey, params?: Record<string, string | number>) => {
    let value: string = locale === 'ru'
      ? russianEditorialOverrides[key] || (translations.ru as Record<string, string>)[key] || translations.en[key] || key
      : translations.en[key] || key;
    Object.entries(params || {}).forEach(([param, replacement]) => {
      value = value.split(`{${param}}`).join(String(replacement));
    });
    return value;
  } }), [locale]);
  return createElement(LocaleContext.Provider, { value }, children);
}

export function getMissingTranslationKeys(locale: Locale): TranslationKey[] {
  const localeTranslations = translations[locale] as Partial<Record<TranslationKey, string>>;
  return (Object.keys(translations.en) as TranslationKey[]).filter((key) => (
    !localeTranslations[key]
    && !(locale === 'ru' && russianEditorialOverrides[key])
  ));
}

export function useLocale() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error('useLocale must be used inside LocaleProvider');
  return context;
}
